mapper.select:
select uad.id id,uad.money money,uad.create_time createTime,uad.title title,uad.business_id businessId,up.phone userTel,po.org_id orgId,
po.org_name orgName,po.user_id userId,po.user_name userName,po.case_name caseName,po.case_no caseNo
from user_account_detail uad LEFT JOIN user_promoted up on uad.user_id=up.user_id LEFT JOIN promotion_outlay po on uad.business_id=po.id
where uad.user_id=#{userId,jdbcType=BIGINT}
order by uad.create_time desc limit #{pageIndex} , #{pageSize}
